// threads handle 4 contiguous "inner" columns at once, turning the
// per-reduce-step global load into a single 128-bit transaction and
// improving effective memory bandwidth utilization.
__global__ void max_reduce_dim1_kernel_float4(
    const float* __restrict__ X,
    float* __restrict__ Y,
    int Outer, int Reduce, int Inner, int InnerVec)
{
  int64_t total  = (int64_t)Outer * (int64_t)InnerVec;
  int64_t idx    = (int64_t)blockIdx.x * blockDim.x + threadIdx.x;
  int64_t stride = (int64_t)blockDim.x * gridDim.x;
  for (; idx < total; idx += stride) {
    int b = (int)(idx / InnerVec);
    int g = (int)(idx % InnerVec);
    int i = g * 4;
    const float* __restrict__ rowbase =
        X + (int64_t)b * (int64_t)Reduce * (int64_t)Inner + (int64_t)i;
    float4 maxv = __ldg(reinterpret_cast<const float4*>(rowbase));
    for (int r = 1; r < Reduce; ++r) {
      const float4 v = __ldg(reinterpret_cast<const float4*>(
          rowbase + (int64_t)r * (int64_t)Inner));
      maxv.x = v.x > maxv.x ? v.x : maxv.x;
      maxv.y = v.y > maxv.y ? v.y : maxv.y;
      maxv.z = v.z > maxv.z ? v.z : maxv.z;
      maxv.w = v.w > maxv.w ? v.w : maxv.w;
    }
    int64_t outbase = (int64_t)b * (int64_t)Inner + (int64_t)i;
    Y[outbase]     = maxv.x;
    Y[outbase + 1] = maxv.y;
    Y[outbase + 2] = maxv.z;
    Y[outbase + 3] = maxv.w;
  }
}
// Scalar fallback for the leftover columns when Inner is not divisible by 4.
template <typename T>
__global__ void max_reduce_dim1_kernel_rem(
    const T* __restrict__ X,
    T* __restrict__ Y,
    int Outer, int Reduce, int Inner, int IStart, int ICount)
{
  int64_t total  = (int64_t)Outer * (int64_t)ICount;
  int64_t idx    = (int64_t)blockIdx.x * blockDim.x + threadIdx.x;
  int64_t stride = (int64_t)blockDim.x * gridDim.x;
  for (; idx < total; idx += stride) {
    int b  = (int)(idx / ICount);
    int ii = (int)(idx % ICount);
    int i  = IStart + ii;
    const T* __restrict__ base =
        X + (int64_t)b * (int64_t)Reduce * (int64_t)Inner + (int64_t)i;
    T maxval = __ldg(base);
    for (int r = 1; r < Reduce; ++r) {
      T v = __ldg(base + (int64_t)r * (int64_t)Inner);
      maxval = v > maxval ? v : maxval;
    }
    Y[(int64_t)b * (int64_t)Inner + (int64_t)i] = maxval;
  }
}
template <typename KernelFunc>
static int compute_full_wave_blocks(KernelFunc kernel, int threads, int64_t blocks_needed) {
  static int num_sms = 0;
  if (num_sms == 0) {
    int device = 0;
    cudaGetDevice(&device);
    cudaDeviceGetAttribute(&num_sms, cudaDevAttrMultiProcessorCount, device);
    if (num_sms <= 0) num_sms = 1;
  }
  int blocks_per_sm = 0;
  cudaOccupancyMaxActiveBlocksPerMultiprocessor(&blocks_per_sm, kernel, threads, 0);
  if (blocks_per_sm <= 0) blocks_per_sm = 1;
  int64_t full_wave = (int64_t)num_sms * (int64_t)blocks_per_sm;
  if (full_wave <= 0) full_wave = num_sms;
  if (blocks_needed < 1) blocks_needed = 1;
  int64_t waves = (blocks_needed + full_wave - 1) / full_wave;
  int64_t blocks = waves * full_wave;
  int64_t max_blocks = 65535;
  if (blocks > max_blocks) {
    int64_t waves_fit = max_blocks / full_wave;
    if (waves_fit < 1) waves_fit = 1;
    blocks = waves_fit * full_wave;
  }
  if (blocks < 1) blocks = full_wave;
  if (blocks > max_blocks) blocks = max_blocks;
  return (int)blocks;
}
torch::Tensor max_reduce_dim_forward(torch::Tensor x, int64_t dim) {
  TORCH_CHECK(x.is_cuda(), "x must be a CUDA tensor");
  int64_t ndim = x.dim();
  if (dim < 0) dim += ndim;
  TORCH_CHECK(dim >= 0 && dim < ndim, "dim out of range");
  auto x_c = x.contiguous();
  int64_t outer = 1;
  for (int64_t d = 0; d < dim; ++d) outer *= x_c.size(d);
  int64_t reduce_size = x_c.size(dim);
  int64_t inner = 1;
  for (int64_t d = dim + 1; d < ndim; ++d) inner *= x_c.size(d);
  std::vector<int64_t> out_shape;
  for (int64_t d = 0; d < ndim; ++d) {
    if (d != dim) out_shape.push_back(x_c.size(d));
  }
  auto y = torch::empty(out_shape, x_c.options());
  constexpr int Threads = 256;
  int64_t max_blocks = 65535;
  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
  bool use_float4 = (x_c.scalar_type() == at::kFloat) &&
      ((reinterpret_cast<uintptr_t>(x_c.data_ptr<float>()) % 16) == 0) &&
      (inner >= 4) && (inner % 4 == 0);
  if (use_float4) {
    int64_t inner_vec = inner / 4;
    int64_t rem = inner % 4;
    if (inner_vec > 0) {
      int64_t total_vec = outer * inner_vec;
      int64_t blocks_needed = (total_vec + Threads - 1) / Threads;
      int blocks = compute_full_wave_blocks(max_reduce_dim1_kernel_float4, Threads, blocks_needed);
      max_reduce_dim1_kernel_float4<<<blocks, Threads, 0, stream>>>(
          x_c.data_ptr<float>(), y.data_ptr<float>(),
          (int)outer, (int)reduce_size, (int)inner, (int)inner_vec);
    }
    if (rem > 0) {
      int64_t total_rem = outer * rem;
      int64_t blocks_needed = (total_rem + Threads - 1) / Threads;
      int blocks = compute_full_wave_blocks(max_reduce_dim1_kernel_rem<float>, Threads, blocks_needed);
      max_reduce_dim1_kernel_rem<float><<<blocks, Threads, 0, stream>>>(
          x_c.data_ptr<float>(), y.data_ptr<float>(),
          (int)outer, (int)reduce_size, (int)inner,
          (int)(inner_vec * 4), (int)rem);
    }
  } else {
    dim3 block(Threads);
    int64_t grid_x64 = (inner + Threads - 1) / Threads;
    if (grid_x64 < 1) grid_x64 = 1;
    if (grid_x64 > 65535) grid_x64 = 65535;
    int64_t grid_y64 = outer;
    if (grid_y64 < 1) grid_y64 = 1;
    if (grid_y64 > 65535) grid_y64 = 65535;
    dim3 grid((unsigned)grid_x64, (unsigned)grid_y64);
    AT_DISPATCH_FLOATING_TYPES(x_c.scalar_type(), "max_reduce_dim1_kernel", ([&] {
      max_reduce_dim1_kernel<scalar_t><<<grid, block, 0, stream>>>(
          x_c.data_ptr<scalar_t>(),
          y.data_ptr<scalar_t>(),
          (int)outer, (int)reduce_size, (int)inner
      );
    }));
  }
  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "max_reduce_dim1_kernel launch failed: ", cudaGetErrorString(err));
  return y;
}
